# Generated by manage.py generate_test_cases.
import json
from datetime import timedelta
from zoneinfo import ZoneInfo

from django.http import HttpResponse

from bloomerp.models.communication.calendar import CalendarEvent
from bloomerp.models.communication.inbox.inbox import Inbox
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.tests.communication.inbox_calendar_fixtures import InboxCalendarFixtures


class TestAvailabilityComponent(InboxCalendarFixtures, BloomerpComponentTestCase):
    """Tests function `availability` from `bloomerp/components/communication/calendar/availability.py`."""

    view_name = "components_calendar_availability"

    def extendedSetup(self) -> None:
        """Create separate participant calendars without giving the actor inbox access."""
        self.prepare_calendar()
        self.owner_calendar = Inbox.objects.create(
            user=self.owner, name="Owner personal calendar", selected=True
        )
        self.outsider_calendar = Inbox.objects.create(
            user=self.outsider, name="Other participant calendar", selected=True
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Describe the observable request contracts for this endpoint."""
        query = {
            "day": self.today.isoformat(),
            "timezone": "UTC",
            "users": str(self.owner.pk),
        }
        return [
            RequestScenario(
                name="Availability requires login",
                query_params=query,
                expected=ExpectedResult(status_code=302),
            ),
            RequestScenario(
                name="Readable users expose only free busy intervals",
                user=self.actor,
                query_params=query,
                expected=ExpectedResult(response_validators=self.private_busy),
            ),
            RequestScenario(
                name="Unreadable participants are omitted",
                user=self.owner,
                query_params={**query, "users": str(self.outsider.pk)},
                expected=ExpectedResult(response_validators=self.self_only),
            ),
            RequestScenario(
                name="Invalid date is rejected",
                user=self.actor,
                query_params={**query, "day": "invalid"},
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Invalid timezone is rejected",
                user=self.actor,
                query_params={**query, "timezone": "invalid"},
                expected=ExpectedResult(status_code=400),
            ),
            RequestScenario(
                name="Availability is read only",
                user=self.actor,
                method="POST",
                expected=ExpectedResult(status_code=405),
            ),
        ]

    def private_busy(self, response: HttpResponse) -> bool:
        """Return only identities, labels, and busy intervals, with private cache headers."""
        people = response.json()["users"]
        return (
            any(person["busy"] for person in people)
            and all(
                set(person) == {"id", "label", "available", "busy"} for person in people
            )
            and self.timed.title not in response.content.decode()
            and response["Cache-Control"] == "private, no-store"
        )

    def self_only(self, response: HttpResponse) -> bool:
        """A user without user-view grants may inspect only their own availability."""
        return [person["id"] for person in response.json()["users"]] == [
            str(self.owner.pk)
        ]

    def test_availability_uses_readable_users_instead_of_actor_inbox_permissions(
        self,
    ) -> None:
        """Readable people expose deduplicated busy intervals across owned and shared inboxes only."""
        from django.contrib.auth import get_user_model

        from bloomerp.communication.utils.permissions import accessible_inboxes
        from bloomerp.components.communication.calendar.availability import (
            calendar_availability,
        )
        from bloomerp.permissions.definition import RowPolicyRuleContent
        from bloomerp.permissions.manager import PolicyManager, UserPolicyManager

        model = get_user_model()
        PolicyManager.create_policy(
            model,
            global_permissions=["view"],
            field_permissions={"username": ["view"]},
            row_permissions=[
                RowPolicyRuleContent(
                    permissions=["view"],
                    conditions=[
                        {
                            "field_path": "id",
                            "lookup_id": "equals",
                            "value": str(self.outsider.pk),
                        },
                    ],
                )
            ],
        ).assign_user(self.owner)
        shared = Inbox.objects.create(user=self.actor, name="Private shared calendar")
        shared.shared_with_users.add(self.outsider)
        private = self.create_event("Private participant meeting")
        private.inboxes.add(self.outsider_calendar, shared)
        shared_only = self.create_event(
            "Private shared meeting",
            start=self.start + timedelta(hours=4),
            end=self.start + timedelta(hours=5),
        )
        shared_only.inboxes.add(shared)
        self.assertFalse(
            accessible_inboxes(self.owner)
            .filter(pk__in=[shared.pk, self.outsider_calendar.pk])
            .exists()
        )
        self.assertFalse(
            UserPolicyManager(self.owner).has_global_permission(CalendarEvent, "view")
        )
        results = calendar_availability(
            self.owner,
            [str(self.outsider.pk), str(self.actor.pk)],
            self.today,
            ZoneInfo("UTC"),
        )
        users = {item["id"]: item for item in results}
        self.assertNotIn(str(self.actor.pk), users)
        participant = users[str(self.outsider.pk)]
        self.assertTrue(participant["available"])
        self.assertEqual(len(participant["busy"]), 2)
        self.assertEqual(set(participant), {"id", "label", "available", "busy"})
        self.assertNotIn(private.title, json.dumps(results))
        self.assertNotIn(shared.name, json.dumps(results))

    def test_availability_hides_users_without_a_user_view_grant(self) -> None:
        """Knowing a user's ID does not reveal their availability without access to that user."""
        from bloomerp.components.communication.calendar.availability import (
            calendar_availability,
        )

        result = calendar_availability(
            self.owner,
            [str(self.outsider.pk)],
            self.today,
            ZoneInfo("UTC"),
        )
        self.assertEqual([item["id"] for item in result], [str(self.owner.pk)])
        self.assertTrue(result[0]["available"])
        self.assertTrue(result[0]["busy"])
